"use client";
/* Shel, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Shel(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("shel"); }, []);
  return React.createElement("piix-pal", { "pal": "shel", ...piixAttrs(props) });
}

export default Shel;
